import * as React from "react";
import { fireEvent, render, screen, waitFor } from "@testing-library/react";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import * as stories from "./Collapsible.stories";
import Collapsible from "./Collapsible";

const { Basic } = composeStories(stories) as any;

describe("Collapsible component", () => {
  beforeEach(() => {
    // not implemented in jsdom
    window.scrollTo = jest.fn();
  });

  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("passes through props", () => {
    render(<Collapsible title="summary" expanded data-testid="collapsible" />);
    expect(screen.getByTestId("collapsible")).toBeTruthy();
  });

  it("expand or collapse content on click", async () => {
    const onChange = jest.fn();
    render(
      <Collapsible title="summary" onChange={onChange}>
        details
      </Collapsible>
    );
    const button = screen.getByRole("button", { name: /summary/ });
    expect(screen.queryByRole("region")).not.toBeInTheDocument();

    // expand
    fireEvent.click(button);
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenLastCalledWith(expect.anything(), true);
    expect(screen.getByRole("region")).toBeInTheDocument();

    // collapse
    fireEvent.click(button);
    expect(onChange).toHaveBeenCalledTimes(2);
    expect(onChange).toHaveBeenLastCalledWith(expect.anything(), false);
    await waitFor(() => {
      expect(screen.queryByRole("region")).not.toBeInTheDocument();
    });
  });
  
  it("allow custom title", () => {
    render(<Collapsible title={<div data-testid="collapsible-title">test</div>}  />);
    expect(screen.getByTestId("collapsible-title")).toBeTruthy();
  });
});
